<script setup lang="ts">import{computed}from'vue';import{useRenameStore}from'../../stores/rename';const s=useRenameStore();const rows=computed(()=>s.items.map(i=>({...i,relative:i.source.slice(s.root.length).replace(/^[/\\]/,'').split(/[/\\]/).slice(0,-1).join('\\')||'.',old:i.source.split(/[/\\]/).pop(),next:i.target.split(/[/\\]/).pop()})));const kind=(v:string)=>v==='文件夹'?'▣':'▤';const status=(v:string)=>v==='可修改'?'●':v==='名称未变化'?'○':v==='已匹配'?'◆':'▲'</script>
<template><el-table :data="rows" height="100%" empty-text="输入查找内容并扫描后，匹配结果会显示在这里"><el-table-column label="类型" width="58" align="center"><template #default="p"><el-tooltip :content="p.row.kind"><span class="icon">{{kind(p.row.kind)}}</span></el-tooltip></template></el-table-column><el-table-column prop="relative" label="所在目录" min-width="130" show-overflow-tooltip/><el-table-column prop="old" label="原名称" min-width="150" show-overflow-tooltip/><el-table-column prop="next" label="新名称" min-width="170" show-overflow-tooltip><template #default="p"><span class="new-name">{{p.row.next}}</span></template></el-table-column><el-table-column label="状态" width="62" align="center"><template #default="p"><el-tooltip :content="p.row.status"><span class="status">{{status(p.row.status)}}</span></el-tooltip></template></el-table-column><el-table-column label="说明" width="62" align="center"><template #default="p"><el-tooltip :content="p.row.detail"><el-button text circle aria-label="查看说明" @click="$emit('details',p.row)">ⓘ</el-button></el-tooltip></template></el-table-column></el-table></template><style scoped>.icon,.status{font-size:17px}.new-name{color:var(--primary);font-weight:700}</style>
